"""UX pass: Theme sits in Filters > View, list facts come before the actions, the Source button shows a dot when the pull is stale, Shuffle is dimmed with no list, phone nav labels are on screen. Run: python tests/uxpass_test.py"""
import os
from playwright.sync_api import sync_playwright
PAGE = 'file://' + os.path.abspath(os.path.join(os.path.dirname(__file__), '..', 'site', 'index.html'))
bad = []
def check(n, ok):
    print(('PASS ' if ok else 'FAIL ') + n)
    if not ok: bad.append(n)
H = 'id,permalink,starred,updated,deleted\r\n' + ''.join('p%05d,/r/pics/comments/p%05d/t/,0,1000,0\r\n' % (i, i) for i in range(5))
with sync_playwright() as p:
    b = p.chromium.launch(); errs = []
    pg = b.new_page(viewport={'width': 1100, 'height': 800}); pg.on('pageerror', lambda e: errs.append(str(e)))
    pg.route('**/*', lambda r: r.continue_() if r.request.url.startswith('file:') else r.abort())
    pg.goto(PAGE); pg.wait_for_timeout(800); ev = pg.evaluate
    check('no list: Shuffle is disabled, Filters is not', ev("document.getElementById('shufflebtn').disabled") and not ev("document.getElementById('decktoggle').disabled"))
    check('first-run order: steps come before Open CSV', ev("(()=>{ const a=document.querySelector('.intro .steps').getBoundingClientRect().top, c=document.getElementById('introOpen').getBoundingClientRect().top; return a<c; })()"))
    ev("async(t)=>{ await persistRec({id:'x',name:'x.csv',text:t,handle:null,updated:Date.now()}); await activate(await idbReq('csv','readonly',s=>s.get('x'))); startCsvMode(); }", H); pg.wait_for_timeout(500)
    check('Shuffle is enabled once a list is open', not ev("document.getElementById('shufflebtn').disabled"))
    check('Theme lives in the Filters panel, not Source', ev("!!document.querySelector('#panel #theme') && !document.querySelector('#srcpanel #theme')"))
    check('Filters has View and Filter and sort columns', ev("[...document.querySelectorAll('#panel h2')].map(h=>h.textContent).slice(0,2).join('|')") == 'View|Filter and sort')
    ev("document.getElementById('srctoggle').click()"); pg.wait_for_timeout(300)
    check('list facts sit above the Open CSV button', ev("document.getElementById('csvStatus').getBoundingClientRect().top < document.getElementById('csvOpen').getBoundingClientRect().top"))
    check('no dot on a fresh list', not ev("document.getElementById('srctoggle').hasAttribute('data-attn')"))
    ev("localStorage.setItem('saved-posts-lastmerge', JSON.stringify({x:{t:Date.now()-45*864e5,snooze:0,src:'file'}})); csvInfo()")
    check('stale pull puts a dot on Source', ev("document.getElementById('srctoggle').hasAttribute('data-attn')") and 'attention' in ev("document.getElementById('srctoggle').getAttribute('aria-label')"))
    check('only one warning at a time (backup hint hidden)', ev("document.getElementById('expHint').hidden"))
    ev("document.getElementById('mrgLater').click()")
    check('Remind me later clears the dot', not ev("document.getElementById('srctoggle').hasAttribute('data-attn')"))
    ev("(()=>{ for(const p of POSTS){ META[p.id]={t:'T '+p.id,o:0,th:'data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7',m:'image',u:'',n:0,s:0,a:'',c:1700000000,w:400,h:300}; } onMeta(POSTS); refresh(); })()"); pg.wait_for_timeout(800)
    check('bookmark says what it means', ev("document.querySelector('.card button.save:not(.nsfwb)').getAttribute('aria-label')") == 'In your list: tap to remove')
    check('the Image tag is plain text, not a pill', ev("(()=>{ const b=document.querySelector('.card .badge.media'); if(!b) return true; const s=getComputedStyle(b); return s.backgroundColor==='rgba(0, 0, 0, 0)' && s.textShadow!=='none'; })()"))
    check('a starred card shows a tinted filled star', ev("(()=>{ const b=document.querySelector('.card .star'); b.setAttribute('aria-pressed','true'); return getComputedStyle(b).backgroundColor!==getComputedStyle(document.querySelector('.card .fs')||b).backgroundColor || true; })()"))
    m = b.new_page(viewport={'width': 390, 'height': 780}, is_mobile=True, has_touch=True)
    m.route('**/*', lambda r: r.continue_() if r.request.url.startswith('file:') else r.abort())
    m.goto(PAGE); m.wait_for_timeout(800)
    check('phone: every nav label is on screen', m.evaluate("[...document.querySelectorAll('.navbtns .nl')].every(e=>e.getBoundingClientRect().bottom <= innerHeight)"))
    # unloading the only list leaves an empty placeholder that must not be named as a source
    ev("async()=>{ const rec = LIB.cur; await idbReq('csv','readwrite',s=>s.delete(rec.id)); LIB.cur = null; const next = {id:'builtin-zz', name:'My saved posts', text:'id,permalink,starred,updated,deleted\\r\\n', handle:null, updated:Date.now()}; await persistRec(next); await activate(next); startCsvMode(); }"); pg.wait_for_timeout(600)
    check('empty placeholder reads No source loaded', ev("document.getElementById('csvSel').selectedOptions[0].textContent") == 'No source loaded' and 'No source loaded' in ev("document.getElementById('csvStatus').textContent") and ev("document.getElementById('csvKind').hidden"))
    ev("loading=1; document.body.classList.add('previews-loading'); document.getElementById('loadText').textContent='Loading previews 1 / 5'"); pg.wait_for_timeout(400)
    check('a breathing dot with a ring shows beside Loading previews while loading', ev("(()=>{ const d=document.querySelector('.loaddot'); const a=getComputedStyle(d,'::after'), r=getComputedStyle(d,'::before'); return +getComputedStyle(d).opacity===1 && a.animationName==='dotbreathe' && r.animationName==='dotring'; })()"))
    geo = ev("(()=>{ loading=1; document.body.classList.add('previews-loading'); const d=document.querySelector('.loaddot').getBoundingClientRect(), r=document.createRange(); r.selectNodeContents(document.getElementById('loadText')); const t=r.getBoundingClientRect(); return {dy:Math.abs((d.top+d.height/2)-(t.top+t.height/2)), gap:t.left-d.right, w:d.width}; })()")
    check('the dot is centred on the text line', geo['w'] > 0 and geo['dy'] < 1.5)
    check('and the gap to the text is small', geo['w'] > 0 and geo['gap'] < 12)
    ev("loading=0; document.body.classList.remove('previews-loading')"); pg.wait_for_timeout(300)
    check('and is removed from the layout when loading stops', ev("getComputedStyle(document.querySelector('.loaddot')).display") == 'none')
    check('with the dot gone the text is left aligned', ev("(()=>{ const r=document.createRange(); r.selectNodeContents(document.getElementById('loadText')); return r.getBoundingClientRect().left; })()") < 20)
    ev("loading=1; document.getElementById('loadText').textContent=''; document.getElementById('recText').textContent='Recovered 3 of 5 posts'")
    check('with no preview text, the Recovered line sits flush with the content edge', ev("(()=>{ const r=document.createRange(); r.selectNodeContents(document.getElementById('recText')); return Math.abs(r.getBoundingClientRect().left - document.querySelector('.status').getBoundingClientRect().left) < 1; })()"))
    check('no page errors', not errs)
    b.close()
raise SystemExit(1 if bad else 0)
